 protected override async void OnStartup(StartupEventArgs e){base.OnStartup(e);DispatcherUnhandledException+=OnDispatcherUnhandledException;_host=Host.CreateDefaultBuilder().ConfigureServices((context,services)=>{var provider=context.Configuration["Database:Provider"]??"Sqlite";var connectionString=context.Configuration["Database:ConnectionString"]??"Data Source=pos-local.db";services.AddDbContextFactory<AppDbContext>(options=>{if(provider.Equals("SqlServer",StringComparison.OrdinalIgnoreCase))options.UseSqlServer(connectionString,sql=>sql.EnableRetryOnFailure());else options.UseSqlite(connectionString);});services.AddSingleton<CrashLogger>();services.AddSingleton<UnitConversionService>();services.AddSingleton<UnitConversionGraph>();services.AddSingleton<InventoryService>();services.AddSingleton<InventoryBalanceService>();services.AddSingleton<InventoryOperationsService>();services.AddSingleton<OpeningStockService>();services.AddSingleton<PricingCalculator>();services.AddSingleton<LocalizationService>();services.AddSingleton<IPasswordHasher,PasswordHasher>();services.AddSingleton<SessionContext>();services.AddSingleton<PermissionService>();services.AddSingleton<ManagerAuthorizationService>();services.AddSingleton<DatabaseAuthenticationService>();services.AddSingleton<ApplicationSeeder>();services.AddSingleton<UserAdministrationService>();services.AddSingleton<BarcodeLookupService>();services.AddSingleton<SalePostingService>();services.AddSingleton<PurchasePostingService>();services.AddSingleton<PurchaseReturnPostingService>();services.AddSingleton<SalesReturnPostingService>();services.AddSingleton<CashRegisterService>();services.AddSingleton<ReportQueryService>();services.AddSingleton<AccountStatementService>();services.AddSingleton<CustomerPaymentService>();services.AddSingleton<SupplierPaymentService>();services.AddSingleton<DatabaseBackupService>();services.AddSingleton<VerificationRunner>();services.AddSingleton<IReceiptPrinter,WindowsPrintService>();services.AddSingleton<IDocumentPrinter,WindowsPrintService>();services.AddSingleton<ILabelPrinter,WindowsPrintService>();services.AddSingleton<ISyncConflictResolver,DefaultSyncConflictResolver>();services.AddHttpClient<ISyncTransport,HttpSyncTransport>();services.AddSingleton<SyncProcessor>();services.AddLogging(builder=>builder.AddConsole());services.AddTransient<LoginWindow>();services.AddTransient<PosWindow>();services.AddTransient<ProductManagementWindow>();services.AddTransient<CategoryManagementWindow>();services.AddTransient<StoreManagementWindow>();services.AddTransient<InventoryManagementWindow>();services.AddTransient<PromotionsWindow>();services.AddTransient<CashRegisterWindow>();services.AddTransient<ReportsWindow>();services.AddTransient<SettingsWindow>();services.AddTransient<AccountsWindow>();services.AddTransient<OpeningStockWindow>();services.AddSingleton<MainWindow>();}).Build();_crashLogger=_host.Services.GetRequiredService<CrashLogger>();await _host.StartAsync();if(e.Args.Any(x=>string.Equals(x,"--verify",StringComparison.OrdinalIgnoreCase))){var results=await _host.Services.GetRequiredService<VerificationRunner>().RunAllAsync();foreach(var result in results)Console.WriteLine($"[{(result.Passed?"PASS":"FAIL")}] {result.Name}{(result.Error is null?string.Empty:$": {result.Error}")}");Shutdown(results.All(x=>x.Passed)?0:1);return;}await using(var scope=_host.Services.CreateAsyncScope()){var factory=scope.ServiceProvider.GetRequiredService<IDbContextFactory<AppDbContext>>();await using var db=await factory.CreateDbContextAsync();await db.Database.EnsureCreatedAsync();await EnsureSchemaAsync(db);await scope.ServiceProvider.GetRequiredService<ApplicationSeeder>().SeedAsync();}_host.Services.GetRequiredService<LoginWindow>().Show();}
 private static async Task EnsureSchemaAsync(AppDbContext db){var isSqlServer=string.Equals(db.Database.ProviderName,"Microsoft.EntityFrameworkCore.SqlServer",StringComparison.OrdinalIgnoreCase);var connection=db.Database.GetDbConnection();if(connection.State!=ConnectionState.Open)await connection.OpenAsync();await using var command=connection.CreateCommand();async Task<bool> Exists(string table,string column){command.CommandText=isSqlServer?$"SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='{table}' AND COLUMN_NAME='{column}'":$"SELECT COUNT(*) FROM pragma_table_info('{table}') WHERE name='{column}'";return Convert.ToInt32(await command.ExecuteScalarAsync())>0;}async Task AddRequired(string table,string column,string ss,string sqlite){if(await Exists(table,column))return;command.CommandText=isSqlServer?$"ALTER TABLE [{table}] ADD [{column}] {ss} NOT NULL DEFAULT 0":$"ALTER TABLE {table} ADD COLUMN {column} {sqlite} NOT NULL DEFAULT 0";await command.ExecuteNonQueryAsync();}async Task AddNullable(string table,string column,string ss,string sqlite){if(await Exists(table,column))return;command.CommandText=isSqlServer?$"ALTER TABLE [{table}] ADD [{column}] {ss} NULL":$"ALTER TABLE {table} ADD COLUMN {column} {sqlite} NULL";await command.ExecuteNonQueryAsync();}
  await AddRequired("ProductUnits","WholesalePrice","decimal(18,2)","decimal(18,2)");await AddRequired("ProductUnits","WholesaleWholesalePrice","decimal(18,2)","decimal(18,2)");await AddNullable("Promotions","ProductId","uniqueidentifier","TEXT");await AddNullable("Promotions","UnitId","uniqueidentifier","TEXT");await AddNullable("Promotions","MaxQuantity","decimal(18,6)","decimal(18,6)");await AddRequired("Promotions","ConsumedQuantity","decimal(18,6)","decimal(18,6)");command.CommandText=isSqlServer?"IF OBJECT_ID('HeldSales','U') IS NULL CREATE TABLE HeldSales (Id uniqueidentifier NOT NULL PRIMARY KEY, CreatedAtUtc datetime2 NOT NULL, UpdatedAtUtc datetime2 NULL, Reference nvarchar(80) NOT NULL, CashierId uniqueidentifier NOT NULL, Payload nvarchar(max) NOT NULL, IsReleased bit NOT NULL DEFAULT 0)":"CREATE TABLE IF NOT EXISTS HeldSales (Id TEXT NOT NULL PRIMARY KEY, CreatedAtUtc TEXT NOT NULL, UpdatedAtUtc TEXT NULL, Reference TEXT NOT NULL, CashierId TEXT NOT NULL, Payload TEXT NOT NULL, IsReleased INTEGER NOT NULL DEFAULT 0)";await command.ExecuteNonQueryAsync();}
